package com.activitycounter.listeners.core;

import com.activitycounter.ActivityCounterConfig;
import com.activitycounter.PluginConstants;
import com.activitycounter.listeners.AbstractListenerNode;
import com.activitycounter.models.Category;
import com.activitycounter.models.TrackedActivity;
import static com.activitycounter.models.TrackedActivity.MAX_TRACKING_ID;
import java.util.Arrays;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

/**
 * Class that handles plugin configurations
 */
@Singleton
public class ConfigListener extends AbstractListenerNode
{
	@Inject
	private ActivityCounterConfig config;

	@Inject
	private ConfigManager configManager;

	private final static String HIDDEN_ACTIVITIES_CONFIG_KEY = "hiddenActivities";
	private final static String ACTIVITY_SCORES_CONFIG_KEY = "activityScores";

	private final boolean[] visibilityCache = new boolean[MAX_TRACKING_ID + 1];
	private final int[] categorySortCache = new int[Category.values().length];
	private final float[] scoreCache = new float[MAX_TRACKING_ID + 1];

	/**
	 * Initializes/rebuilds all configuration caches
	 */
	public void buildAllCaches() {
		parseHiddenActivities();
		cacheCategorySortOrder();
		parseActivityScores();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (!event.getGroup().equals(PluginConstants.CONFIG_GROUP)) return;

		String key = event.getKey();

		if (key.equals(HIDDEN_ACTIVITIES_CONFIG_KEY)) {
			parseHiddenActivities();
		} else if (key.equals(ACTIVITY_SCORES_CONFIG_KEY)) {
			parseActivityScores();
		} else if (key.startsWith("sort")) {
			cacheCategorySortOrder();
		}
	}

	/**
	 * Parses hiddenActivities config and converts it into an array of booleans that indicate what should (not) be shown
	 */
	private void parseHiddenActivities() {
		String hiddenStr = config.hiddenActivities();

		if (hiddenStr == null || hiddenStr.trim().isEmpty()) {
			Arrays.fill(visibilityCache, true);
			return;
		}

		Set<String> hiddenActivitySet = Arrays.stream(hiddenStr.split(","))
			.map(String::trim)
			.collect(Collectors.toSet());

		for (TrackedActivity activity : TrackedActivity.values()) {
			visibilityCache[activity.getId()] = !hiddenActivitySet.contains(activity.getConfigId());
		}
	}

	private void parseActivityScores() {
		String scoresStr = config.activityScores();
		Arrays.fill(scoreCache, 0f);

		if (scoresStr == null || scoresStr.trim().isEmpty()) return;

		String[] entries = scoresStr.split(",");
		for (String entry : entries) {
			String[] parts = entry.split(":");
			if (parts.length == 2) {
				String configId = parts[0].trim();
				try {
					float score = Float.parseFloat(parts[1].trim());
					for (TrackedActivity act : TrackedActivity.values()) {
						if (act.getConfigId().equals(configId)) {
							scoreCache[act.getId()] = score;
							break;
						}
					}
				} catch (NumberFormatException ignored) {}
			}
		}
	}

	/**
	 * Hides an activity by updating the array cache instantly and saving it to the configManager.
	 */
	public void disableActivity(TrackedActivity activity) {
		if (activity == null || !visibilityCache[activity.getId()]) {
			return;
		}

		visibilityCache[activity.getId()] = false;

		StringBuilder newHiddenString = new StringBuilder();
		for (TrackedActivity act : TrackedActivity.values()) {
			if (!visibilityCache[act.getId()]) {
				if (newHiddenString.length() > 0) newHiddenString.append(",");
				newHiddenString.append(act.getConfigId());
			}
		}

		configManager.setConfiguration(PluginConstants.CONFIG_GROUP, HIDDEN_ACTIVITIES_CONFIG_KEY, newHiddenString.toString());
	}

	public boolean isKcVisible(int trackedActivityIndex) {
		if (trackedActivityIndex < 0 || trackedActivityIndex > MAX_TRACKING_ID) return false;
		return visibilityCache[trackedActivityIndex];
	}

	public boolean isKcVisible(TrackedActivity trackedActivity) {
		return visibilityCache[trackedActivity.getId()];
	}

	/**
	 * Fetch the O(1) cached category sort order.
	 */
	public int getCategorySortOrder(Category category) {
		if (category == null) return 99;
		return categorySortCache[category.ordinal()];
	}

	/**
	 * Determine and cache the order in which categories are to be sorted in advance
	 */
	private void cacheCategorySortOrder()
	{
		for (Category category : Category.values()) {
			categorySortCache[category.ordinal()] = fetchCategorySortOrder(category);
		}
	}

	/**
	 * Internal method to pull from the config object.
	 */
	private int fetchCategorySortOrder(Category category)
	{
		switch (category)
		{
			case BOSSES: return config.sortBosses();
			case CHESTS: return config.sortChests();
			case CLUE: return config.sortClue();
			case SLAYER: return config.sortSlayer();
			case AGILITY: return config.sortAgility();
			case EXPERIENCE: return config.sortExperience();
			case LEVELS: return config.sortLevels();
			case BOLTS: return config.sortBoltProcs();
			case OTHER: return config.sortOther();
			case RAIDS: return config.sortRaids();
			case MINI_GAMES: return config.sortMiniGames();
			case MAGIC_SPELLS: return config.sortMagicSpells();
			case COMBAT: return config.sortCombat();
			case SUPPLIES: return config.sortSupplies();
			case SKILLING: return config.sortSkilling();
			case ACHIEVEMENTS: return config.sortAchievements();
			case SAILING: return config.sortSailing();
			case TERTIARY_DROPS: return config.sortTertiaryDrops();
			case RANDOM_EVENTS: return config.sortRandomEvents();
			default: return 99;
		}
	}

	/**
	 * Hides/updates a score and commits it back to the RuneLite ConfigManager.
	 */
	public void setActivityScore(TrackedActivity activity, float score) {
		if (activity == null) return;
		scoreCache[activity.getId()] = score;

		StringBuilder newScoreString = new StringBuilder();
		for (TrackedActivity act : TrackedActivity.values()) {
			float s = scoreCache[act.getId()];
			if (s != 0f) {
				if (newScoreString.length() > 0) newScoreString.append(",");
				newScoreString.append(act.getConfigId()).append(":").append(s);
			}
		}
		configManager.setConfiguration(PluginConstants.CONFIG_GROUP, ACTIVITY_SCORES_CONFIG_KEY, newScoreString.toString());
	}

	public float getScore(int trackingId) {
		if (trackingId < 0 || trackingId > MAX_TRACKING_ID) return 0f;
		return scoreCache[trackingId];
	}
}

package com.activitycounter.listeners.core;

import static com.activitycounter.PluginConstants.EQUIPPED_ITEM_CONTAINER_ID;
import com.activitycounter.listeners.AbstractListenerNode;
import com.activitycounter.listeners.conditional.BoltProcListener;
import com.activitycounter.models.EquipmentWorn;
import com.activitycounter.models.EquippedWeaponType;
import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import static net.runelite.api.gameval.VarPlayerID.COM_MODE;
import static net.runelite.api.gameval.VarbitID.COMBAT_WEAPON_CATEGORY;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Centralized class that listens to changes in the equipped items and acts accordingly.
 */
@Slf4j
@Singleton
public class EquippedItemListener extends AbstractListenerNode
{
	private static final EquippedWeaponType.Stance NULL_STANCE = EquippedWeaponType.UNARMED.getStance(0);

	public static final int WEAPON_SLOT_IDX = EquipmentInventorySlot.WEAPON.getSlotIdx();
	public static final int OFFHAND_SLOT_IDX = EquipmentInventorySlot.SHIELD.getSlotIdx();
	public static final int HEAD_SLOT_IDX = EquipmentInventorySlot.HEAD.getSlotIdx();
	public static final int CHEST_SLOT_IDX = EquipmentInventorySlot.BODY.getSlotIdx();
	public static final int LEG_SLOT_IDX = EquipmentInventorySlot.LEGS.getSlotIdx();
	public static final int ARM_SLOT_IDX = EquipmentInventorySlot.ARMS.getSlotIdx();
	public static final int FOOT_SLOT_IDX = EquipmentInventorySlot.BOOTS.getSlotIdx();
	public static final int BACK_SLOT_IDX = EquipmentInventorySlot.SHIELD.getSlotIdx();
	public static final int NECK_SLOT_IDX = EquipmentInventorySlot.AMULET.getSlotIdx();
	public static final int RING_SLOT_IDX = EquipmentInventorySlot.RING.getSlotIdx();
	public static final int AMMO_SLOT_IDX = EquipmentInventorySlot.AMMO.getSlotIdx();

	@SuppressWarnings("OptionalGetWithoutIsPresent")
	public static final int MAX_EQUIPMENT_SLOT_IDX = Arrays.stream(EquipmentInventorySlot.values())
		.mapToInt(EquipmentInventorySlot::getSlotIdx)
		.max()
		.getAsInt();

	@Inject
	private BoltProcListener boltProcListener;

	private final int[] equippedItemIds = new int[MAX_EQUIPMENT_SLOT_IDX+1];

	// Equipment State
	@Getter
	private EquipmentWorn weapon = null;

	private int equippedAmmoId = -1;
	private boolean combatParamUpdateQueued = false;

	private boolean isInitialized = false;

	@Getter
	private EquippedWeaponType equippedWeaponType;

	@Getter
	private EquippedWeaponType.Stance stance;

	@Inject
	private ClientThread clientThread;

	/**
	 * Sets up routing caches for sound listeners
	 */
	public void initializeRoutingCaches() {
		if (isInitialized) return;

		Arrays.fill(equippedItemIds, -1);
		onLogin();

		isInitialized = true;
	}

	@Override
	public void onRegistered() {
		isInitialized = false;
		clientThread.invokeLater(this::initializeRoutingCaches);
		combatParamUpdateQueued = true;
	}

	private void onLogin()
	{
		ItemContainer equipment = client.getItemContainer(EQUIPPED_ITEM_CONTAINER_ID);
		if (equipment != null)
		{
			processContainer(equipment);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			onLogin();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == EQUIPPED_ITEM_CONTAINER_ID)
		{
			processContainer(event.getItemContainer());
		}
	}

	/**
	 * Updates combat parameters such as weapon type equipped and attack stance used
	 */
	private void updateCombatParameters()
	{
		equippedWeaponType = EquippedWeaponType.getByVarbitValue(client.getVarbitValue(COMBAT_WEAPON_CATEGORY));

		int attackStyleIndex = client.getVarpValue(COM_MODE);
		stance = equippedWeaponType != null ? equippedWeaponType.getStance(attackStyleIndex) : NULL_STANCE;
		combatParamUpdateQueued = equippedWeaponType == null;
	}

//	@Subscribe
//	public void onGameTick(GameTick event)
//	{
//		if (combatParamUpdateQueued)
//		{
//			updateCombatParameters();
//		}
//	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == COMBAT_WEAPON_CATEGORY || event.getVarpId() == COM_MODE)
		{
			combatParamUpdateQueued = true;
		}
	}

	/**
	 * Synchronizes the entire tracking array with the current state of the equipment container,
	 * then triggers specialized side-effects for specific slots.
	 */
	private void processContainer(ItemContainer inventory)
	{
		if (inventory == null)
		{
			Arrays.fill(equippedItemIds, -1);
			updateWeaponWorn(null);
			updateAmmoWorn(null);
			return;
		}

		Item[] items = inventory.getItems();
		for (int i = 0; i < equippedItemIds.length; i++)
		{
			if (i < items.length && items[i] != null)
			{
				equippedItemIds[i] = items[i].getId();
			}
			else
			{
				equippedItemIds[i] = -1;
			}
		}

		// Fire specific side-effects
		updateWeaponWorn(inventory.getItem(WEAPON_SLOT_IDX));
		updateAmmoWorn(inventory.getItem(AMMO_SLOT_IDX));
	}

	/**
	 * All actions that are to be taken whenever the weapon worn is changed
	 */
	private void updateWeaponWorn(Item item)
	{
		int weaponId = item != null ? item.getId() : -1;
		equippedItemIds[WEAPON_SLOT_IDX] = weaponId;
		weapon = weaponId != -1 ? EquipmentWorn.getEquipment(weaponId) : null;
	}

	/**
	 * All actions that are to be taken whenever the ammo worn is changed
	 */
	private void updateAmmoWorn(Item item)
	{
		int itemId = item != null ? item.getId() : -1;
		if (itemId == equippedAmmoId) return;

		equippedAmmoId = item == null ? -1 : item.getId();
		boltProcListener.setAmmoItem(item);
	}

	public int getHeadId()    { return equippedItemIds[HEAD_SLOT_IDX]; }
	public int getBackId()    { return equippedItemIds[BACK_SLOT_IDX]; }
	public int getNeckId()    { return equippedItemIds[NECK_SLOT_IDX]; }
	public int getWeaponId()  { return equippedItemIds[WEAPON_SLOT_IDX]; }
	public int getChestId()   { return equippedItemIds[CHEST_SLOT_IDX]; }
	public int getOffhandId() { return equippedItemIds[OFFHAND_SLOT_IDX]; }
	public int getLegsId()    { return equippedItemIds[LEG_SLOT_IDX]; }
	public int getGlovesId()  { return equippedItemIds[ARM_SLOT_IDX]; }
	public int getBootsId()   { return equippedItemIds[FOOT_SLOT_IDX]; }
	public int getRingId()    { return equippedItemIds[RING_SLOT_IDX]; }
	public int getAmmoId()    { return equippedItemIds[AMMO_SLOT_IDX]; }
}

package com.activitycounter.listeners.core;

import com.activitycounter.events.ExperienceDrop;
import com.activitycounter.listeners.AbstractListenerNode;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

/**
 * Class that handles stat changes that relate to exp drops / differences specifically.
 */
@Slf4j
@Singleton
public class ExperienceDropListener extends AbstractListenerNode
{
	@Inject
	private EventBus eventBus;

	@Getter
	private int lastExpDropTick = -1;

	private final EnumSet<Skill> skillsGainedLastTick = EnumSet.noneOf(Skill.class);

	private final int[] lastXpTicks = new int[Skill.values().length];
	private final int[] previousXp = new int[Skill.values().length];

	private static final int MAX_SOUND_ID = 10000;

	private final Skill[][] ambiguousSoundMap = new Skill[MAX_SOUND_ID][];

	public ExperienceDropListener()
	{
		Arrays.fill(lastXpTicks, -100);
		Arrays.fill(previousXp, -1);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			Arrays.fill(previousXp, -1);
			skillsGainedLastTick.clear();
			lastExpDropTick = -1;
		}
	}

	@Subscribe(priority=100.0f)
	public void onStatChanged(StatChanged event)
	{
		int skillIdx = event.getSkill().ordinal();
		int newTotalXp = event.getXp();
		int previousTotalXp = previousXp[skillIdx];

		if (previousTotalXp != -1 && newTotalXp > previousTotalXp)
		{
			int xpGained = newTotalXp - previousTotalXp;
			int currentTick = client.getTickCount();

			// If this XP drop is on a new tick, clear the tracker and advance the tick
			if (currentTick > lastExpDropTick)
			{
				lastExpDropTick = currentTick;
				skillsGainedLastTick.clear();
			}

			skillsGainedLastTick.add(event.getSkill());
			lastXpTicks[skillIdx] = currentTick;

			eventBus.post(new ExperienceDrop(event.getSkill(), xpGained, currentTick));
		}

		previousXp[skillIdx] = newTotalXp;
	}

	/**
	 * Returns a read-only view of all skills that received experience on the last active drop tick.
	 */
	public Set<Skill> getSkillsGainedLastTick()
	{
		return Collections.unmodifiableSet(skillsGainedLastTick);
	}

	/**
	 * Given a set of Skills, return the Skill for which a tick was registered most recently.
	 */
	public Skill getMostRecentDrop(Skill... skills)
	{
		Skill mostRecentSkill = null;
		int highestTick = -1;
		int currentTick = client.getTickCount();

		for (Skill skill : skills)
		{
			int dropTick = lastXpTicks[skill.ordinal()];

			if (currentTick - dropTick <= 2 && dropTick > highestTick)
			{
				highestTick = dropTick;
				mostRecentSkill = skill;
			}
		}

		return mostRecentSkill;
	}

	/**
	 * Checks if a specific skill received an experience drop on the most recent registered tick.
	 */
	public boolean hasSkillGainedExpLastTick(Skill skill)
	{
		if (skill == null)
		{
			return false;
		}

		return skillsGainedLastTick.contains(skill);
	}
}

package com.activitycounter.listeners.core;

import static com.activitycounter.PluginConstants.EQUIPPED_ITEM_CONTAINER_ID;
import static com.activitycounter.PluginConstants.INVENTORY_CONTAINER_ID;
import com.activitycounter.listeners.AbstractListenerNode;
import com.activitycounter.listeners.conditional.MagicSpellListener;
import com.activitycounter.models.RuneElement;
import com.activitycounter.models.RuneProvider;
import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
public class InventoryListener extends AbstractListenerNode
{
	@Inject
	private EquippedItemListener equippedItemListener;

	@Inject
	private MagicSpellListener magicSpellListener;

	private static final int N_RUNE_POUCH_SLOTS = 4;

	private final int[] runePouchItemIds = new int[N_RUNE_POUCH_SLOTS];
	private final int[] runePouchAmounts = new int[N_RUNE_POUCH_SLOTS];
	private final int[] runeProviderCounts = new int[RuneProvider.values().length];
	private final int[] runeElementTotals = new int[RuneElement.values().length];

	private boolean requiresRecalculation = false;
	private boolean isInitialized = false;

	public void initializeRoutingCaches()
	{
		if (isInitialized) return;

		Arrays.fill(runePouchItemIds, -1);
		Arrays.fill(runePouchAmounts, 0);
		Arrays.fill(runeProviderCounts, 0);
		Arrays.fill(runeElementTotals, 0);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			recalculateRuneState(false);
			isInitialized = true;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			isInitialized = false;
			requiresRecalculation = false;
			Arrays.fill(runeProviderCounts, 0);
			Arrays.fill(runeElementTotals, 0);
		}
		else
		{
			initializeRoutingCaches();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == INVENTORY_CONTAINER_ID || id == EQUIPPED_ITEM_CONTAINER_ID)
		{
			requiresRecalculation = true;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int id = event.getVarbitId();
		int val = event.getValue();

		switch (id)
		{
			case VarbitID.RUNE_POUCH_QUANTITY_1: runePouchAmounts[0] = val; requiresRecalculation = true; break;
			case VarbitID.RUNE_POUCH_QUANTITY_2: runePouchAmounts[1] = val; requiresRecalculation = true; break;
			case VarbitID.RUNE_POUCH_QUANTITY_3: runePouchAmounts[2] = val; requiresRecalculation = true; break;
			case VarbitID.RUNE_POUCH_QUANTITY_4: runePouchAmounts[3] = val; requiresRecalculation = true; break;
			case VarbitID.RUNE_POUCH_TYPE_1: updateRunePouchType(0, val); requiresRecalculation = true; break;
			case VarbitID.RUNE_POUCH_TYPE_2: updateRunePouchType(1, val); requiresRecalculation = true; break;
			case VarbitID.RUNE_POUCH_TYPE_3: updateRunePouchType(2, val); requiresRecalculation = true; break;
			case VarbitID.RUNE_POUCH_TYPE_4: updateRunePouchType(3, val); requiresRecalculation = true; break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (requiresRecalculation)
		{
			recalculateRuneState(isInitialized);
			requiresRecalculation = false;
			isInitialized = true;
		}
	}

	private void updateRunePouchType(int slot, int pouchId)
	{
		if (pouchId <= 0)
		{
			runePouchItemIds[slot] = -1;
		}
		else
		{
			RuneProvider provider = RuneProvider.getByPouchId(pouchId);
			runePouchItemIds[slot] = (provider != null) ? provider.getItemId() : -1;
		}
	}

	private void recalculateRuneState(boolean trackDeltas)
	{
		int[] nextProviderCounts = new int[RuneProvider.values().length];
		Arrays.fill(runeElementTotals, 0);

		// 1. Tally Inventory Items
		ItemContainer inventory = client.getItemContainer(INVENTORY_CONTAINER_ID);
		if (inventory != null)
		{
			for (Item item : inventory.getItems())
			{
				RuneProvider rp = RuneProvider.getByItemId(item.getId());
				if (rp != null && !rp.isInfinite())
				{
					nextProviderCounts[rp.ordinal()] += item.getQuantity();
				}
			}
		}

		// 2. Tally Rune Pouch Items
		for (int i = 0; i < N_RUNE_POUCH_SLOTS; i++)
		{
			int itemId = runePouchItemIds[i];
			if (itemId != -1)
			{
				RuneProvider rp = RuneProvider.getByItemId(itemId);
				if (rp != null && !rp.isInfinite())
				{
					nextProviderCounts[rp.ordinal()] += runePouchAmounts[i];
				}
			}
		}

		boolean hasDeltas = false;
		int[] consumedDeltas = new int[RuneProvider.values().length];

		if (trackDeltas)
		{
			for (RuneProvider rp : RuneProvider.values())
			{
				if (rp.isInfinite()) continue;

				int oldQty = runeProviderCounts[rp.ordinal()];
				int newQty = nextProviderCounts[rp.ordinal()];

				if (newQty < oldQty)
				{
					consumedDeltas[rp.ordinal()] = oldQty - newQty;
					hasDeltas = true;
				}
			}
		}

		System.arraycopy(nextProviderCounts, 0, runeProviderCounts, 0, nextProviderCounts.length);

		applyInfiniteProvider(RuneProvider.getByItemId(equippedItemListener.getWeaponId()));
		applyInfiniteProvider(RuneProvider.getByItemId(equippedItemListener.getOffhandId()));

		for (RuneProvider rp : RuneProvider.values())
		{
			if (rp.isInfinite()) continue;

			int physicalAmount = runeProviderCounts[rp.ordinal()];
			if (physicalAmount > 0)
			{
				for (RuneElement element : rp.getProvidedElements())
				{
					if (runeElementTotals[element.ordinal()] != -1)
					{
						runeElementTotals[element.ordinal()] += physicalAmount;
					}
				}
			}
		}

		if (hasDeltas)
		{
			magicSpellListener.processRuneDeltas(consumedDeltas);
		}
	}

	private void applyInfiniteProvider(RuneProvider rp)
	{
		if (rp != null && rp.isInfinite())
		{
			for (RuneElement element : rp.getProvidedElements())
			{
				runeElementTotals[element.ordinal()] = -1;
			}
		}
	}

	public int getProviderCount(RuneProvider provider)
	{
		if (provider == null) return 0;
		return runeProviderCounts[provider.ordinal()];
	}

	public int getElementTotal(RuneElement element)
	{
		if (element == null) return 0;
		return runeElementTotals[element.ordinal()];
	}
}

package com.activitycounter.listeners.core;

import com.activitycounter.listeners.AbstractListenerNode;
import com.activitycounter.models.GameMode;
import com.activitycounter.models.SpellBook;
import com.activitycounter.models.TrackedActivity;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

/**
 * Centralized listener that actively tracks player status variables and interface states.
 * Provides O(1) lookups for the player's condition (e.g., active spellbook, wilderness status).
 */
@Slf4j
@Singleton
public class PlayerListener extends AbstractListenerNode
{


	@Getter
	private boolean isBusy = false;

	@Getter
	private boolean inWilderness = false;

	@Getter
	private SpellBook activeSpellBook = null;

	@Getter
	private GameMode gameMode = GameMode.NORMAL;

	private boolean isInitialized = false;

	private static final int[] TRANSFER_INTERFACE_IDS = {
		12, 192, 300, 335, 464, 465, 631, 669, 724
	};

	public void initializeState()
	{
		if (isInitialized) return;

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			updateBusy();
			updateWilderness();
			updateSpellbook();
			updateGameMode();
			isInitialized = true;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			initializeState();
		}
		else
		{
			isInitialized = false;
		}
	}



	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varbitId = event.getVarbitId();

		if (varbitId > -1)
		{
			switch (varbitId)
			{
				case VarbitID.BUSY:
					updateBusy();
					break;
				case VarbitID.SPELLBOOK:
					updateSpellbook();
					plugin.increaseCountByOne(TrackedActivity.SPELLBOOK_CHANGES.getId());
					break;
				case VarbitID.INSIDE_WILDERNESS:
					updateWilderness();
					break;
			}
		}
	}

	private void updateBusy()
	{
		isBusy = client.getVarbitValue(VarbitID.BUSY) == 1;
	}

	private void updateSpellbook()
	{
		activeSpellBook = SpellBook.getById(client.getVarbitValue(VarbitID.SPELLBOOK));
	}

	private void updateWilderness()
	{
		inWilderness = client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1;
	}

	private void updateGameMode()
	{
		gameMode = GameMode.fromVarbitValue(client.getVarbitValue(VarbitID.IRONMAN));
	}

	/**
	 * Determines if the player is currently in an interface or state where runes
	 * could leave the inventory (e.g., banking, dying) without actually being consumed.
	 */
	public boolean isTransferStateActive()
	{
		if (client.getLocalPlayer() != null && client.getLocalPlayer().isDead())
		{
			return true;
		}

		for (int interfaceId : TRANSFER_INTERFACE_IDS)
		{
			if (client.getWidget(interfaceId, 1) != null)
			{
				return true;
			}
		}

		return false;
	}
}

