	}, SpotanimID.XBOWS_DOWN_TO_EARTH_SPOT_ANIM, 2914, TrackedActivity.RED_TOPAZ_BOLT_PROC),

	RUBY("Blood Forfeit", new int[]{
		ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_TIPPED_RUBY_ENCHANTED,
