package com.activitycounter.models;

import java.time.Instant;
import java.util.Collection;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import lombok.Data;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.Skill;

/**
 * Model class for a Session, which describes a set of registered Counts within a manually defined timespan
 */
@Data
public class Session {
	private String id;

	@Getter
	@Setter
	private String sessionName;

	private long accountHash;
	private String accountName;
	private Instant startTime;
	private Instant endTime = null;
	private boolean inProgress;
	private int secondsPassed;
	private String notes;

	private Map<Integer, Count> trackedKills;
	private Map<Skill, Integer> initialXp;
	private Map<Skill, Integer> gainedXp;

	public Session(long accountHash, String accountName) {
		id = UUID.randomUUID().toString();
		this.accountHash = accountHash;
		this.accountName = accountName;
		startTime = Instant.now();
		inProgress = true;
		secondsPassed = 0;
		trackedKills = new HashMap<>();
		initialXp = new HashMap<>();
		gainedXp = new HashMap<>();
	}

	/**
	 * Ensures maps are instantiated.
	 * Crucial for when Gson deserializes older JSON files that lack these fields.
	 */
	private void ensureXpMapsExist() {
		if (initialXp == null) {
			initialXp = new HashMap<>();
		}
		if (gainedXp == null) {
			gainedXp = new HashMap<>();
		}
	}

	public void addKillCount(Count kc) {
		if (trackedKills == null) trackedKills = new HashMap<>();
		trackedKills.put(kc.getTrackingId(), kc);
	}

	public Count getKillCount(int activityId) {
		if (trackedKills == null) trackedKills = new HashMap<>();
		return trackedKills.get(activityId);
	}

	public void addSecond() {
		secondsPassed++;
	}

	public boolean isTracking(int id) {
		if (trackedKills == null) trackedKills = new HashMap<>();
		return trackedKills.containsKey(id);
	}

	public Collection<Count> getAllKillCounts() {
		if (trackedKills == null) trackedKills = new HashMap<>();
		return trackedKills.values();
	}

	public void initializeSkill(Skill skill, int currentXp) {
		ensureXpMapsExist();
		if (!initialXp.containsKey(skill)) {
			initialXp.put(skill, currentXp);
			gainedXp.put(skill, 0);
		}
	}

	public boolean updateSkillXp(Skill skill, int currentXp) {
		ensureXpMapsExist();
		if (initialXp.containsKey(skill)) {
			int gained = currentXp - initialXp.get(skill);
			if (gained > gainedXp.getOrDefault(skill, 0)) {
				gainedXp.put(skill, gained);
				return true;
			}
		}
		return false;
	}

	public Map<Skill, Integer> getGainedXpMap() {
		ensureXpMapsExist();
		return gainedXp;
	}

	public void initializeActivity(Client client, TrackedActivity act) {
		Count kc = new Count(act.getName(), act.getId());

		int baseline = act.getTrackerType().fetchBaseline(client, act);
		kc.setInitialKc(baseline);

		addKillCount(kc);
	}

	/**
	 * Unified update method.
	 * @param newValue Either the increment amount (+1) or the new game state total, depending on TrackerType.
	 * @return true if the sessionKc actually increased.
	 */
	public boolean processActivityUpdate(TrackedActivity act, int newValue) {
		Count kc = getKillCount(act.getId());
		if (kc == null) return false;

		if (kc.getInitialKc() == -1) {
			kc.setInitialKc(newValue);
		}

		int newSessionKc = act.getTrackerType().calculateNewSessionKc(kc, newValue);

		if (newSessionKc > kc.getSessionKc()) {
			kc.setSessionKc(newSessionKc);
			return true;
		}
		return false;
	}
}

